INSERT INTO settings (setting_key,setting_value) VALUES ('keuchik_name','Amanullah, S.Ag.') ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value);
INSERT INTO settings (setting_key,setting_value) VALUES ('keuchik_title','Keuchik Gampong Lamgugob') ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value);
INSERT INTO settings (setting_key,setting_value) VALUES ('keuchik_message','Data jabatan Keuchik terverifikasi hingga 18 Agustus 2026. Susunan perangkat lainnya menunggu pembaruan resmi dari Pemerintah Gampong.') ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value);
INSERT INTO settings (setting_key,setting_value) VALUES ('profile_heading','Profil Gampong Lamgugob') ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value);
INSERT INTO settings (setting_key,setting_value) VALUES ('profile_summary','Gampong Lamgugob berada di Kecamatan Syiah Kuala, Kota Banda Aceh, Mukim Kayee Adang. Data utama wilayah menggunakan sumber BPS, DPMG, Pemerintah Kota Banda Aceh, arsip Pemerintah Gampong, dan sumber akademik yang diberi status verifikasi.') ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value);
INSERT INTO settings (setting_key,setting_value) VALUES ('profile_history','Narasi lokal yang terdokumentasi dalam penelitian akademik menyebut Lamgugob telah ada sejak masa Kesultanan Aceh dan mengaitkan keberadaan makam serta nisan lama dengan jejak permukiman tua. Asal nama Lamgugob juga hidup dalam tradisi lisan masyarakat dan karena itu ditampilkan sebagai cerita masyarakat, bukan fakta historis yang telah dibuktikan melalui arsip primer. Dalam tradisi lisan, nama Lamgugob dikaitkan dengan kata Aceh "gugob" yang merujuk pada keadaan panik dalam sebuah cerita masyarakat tentang kejadian dengan hewan liar. Sejarah ekonomi lokal mencatat kegiatan pertanian, perkebunan, perikanan, perdagangan, serta tradisi Ija Lamgugob sebagai bagian dari warisan lokal. Peurada juga disebut pernah menjadi bagian wilayah Lamgugob sebelum menjadi gampong definitif tersendiri. Unsur sejarah lisan dan budaya tersebut masih memerlukan dokumentasi primer lebih lanjut.') ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value);
INSERT INTO settings (setting_key,setting_value) VALUES ('vision','SATWITA: Sejahtera, Aman, Tertib, Wibawa, Inisiatif, Teguh, dan Asri. Visi ini tercatat dalam sumber Pemerintah Gampong yang dikutip penelitian tahun 2023 dan perlu dikonfirmasi kembali untuk periode pemerintahan berjalan.') ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value);
INSERT INTO settings (setting_key,setting_value) VALUES ('mission','Penguatan pelaksanaan syariat Islam; peningkatan kualitas pelayanan pemerintahan; peningkatan kesehatan masyarakat; penguatan ekonomi lokal; peningkatan pendidikan; pembangunan sarana dan prasarana; pelestarian lingkungan; serta optimalisasi lembaga gampong. Rumusan ini merupakan data terdokumentasi dan perlu dikonfirmasi kembali dengan RPJMG/RKPG terbaru.') ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value);
INSERT INTO settings (setting_key,setting_value) VALUES ('profile_values','SATWITA — Sejahtera, Aman, Tertib, Wibawa, Inisiatif, Teguh, dan Asri.') ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value);
INSERT INTO settings (setting_key,setting_value) VALUES ('profile_commitment','Portal membedakan data terverifikasi, data historis, dan data yang masih perlu konfirmasi. Data yang belum tersedia tidak diisi dengan contoh atau perkiraan.') ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value);
