INSERT INTO settings (setting_key,setting_value) VALUES ('government_summary','Menampilkan perangkat dan lembaga yang telah dipublikasikan Admin. Saat ini data Keuchik telah terverifikasi, sedangkan susunan perangkat lainnya menunggu data primer terbaru.') ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value);
