INSERT INTO settings (setting_key,setting_value) VALUES ('mosque_location_code','H994+R3H') ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value);
INSERT INTO settings (setting_key,setting_value) VALUES ('mosque_history','Masjid Besar Syuhada Lamgugob berkembang di lokasi sekarang sejak akhir dekade 1980-an, setelah masjid sebelumnya di kawasan Lamnyong terdampak proyek penataan Krueng Aceh. Sumber akademik menyebut pembangunan di lokasi sekarang sejak 1988, sementara dokumentasi lain mengaitkan pemindahan dengan proyek sekitar 1989. Nama Syuhada dalam dokumentasi penelitian dikaitkan dengan dua makam yang dipandang sebagai syuhada di kawasan masjid lama, namun identitas lengkap tokoh tersebut tidak dapat dipastikan oleh informan penelitian.') ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value);
INSERT INTO settings (setting_key,setting_value) VALUES ('mosque_data_note','Susunan BKM yang terdokumentasi memiliki masa khidmat 2021–2026. Ketua BKM Dr. Ir. H. Basri A. Bakar masih terverifikasi melalui dokumen 13 Mei 2026, tetapi kepengurusan setelah periode tersebut perlu dikonfirmasi sebelum dianggap sebagai susunan aktif.') ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value);
INSERT INTO settings (setting_key,setting_value) VALUES ('contact_heading','Kontak & Lokasi Kantor Gampong') ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value);
INSERT INTO settings (setting_key,setting_value) VALUES ('contact_summary','Alamat kantor dapat ditampilkan dari sumber pemerintah. Telepon, WhatsApp, email resmi, dan jam pelayanan sengaja dibiarkan kosong sampai diperoleh dari Pemerintah Gampong.') ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value);
INSERT INTO settings (setting_key,setting_value) VALUES ('footer_description','Portal data dan layanan Gampong Lamgugob, Kecamatan Syiah Kuala, Kota Banda Aceh. Konten dinamis dikelola Admin melalui MySQL dan API.') ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value);
INSERT INTO settings (setting_key,setting_value) VALUES ('data_disclaimer','Data inti portal diperiksa ulang sampai 20 September 2026. Statistik penduduk memakai kondisi 2024. Data historis dan data yang masih perlu konfirmasi diberi label khusus dan tidak boleh diperlakukan sebagai data aktif tanpa pembaruan resmi.') ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value);
