INSERT INTO settings (setting_key,setting_value) VALUES ('seo_description','Portal Gampong Lamgugob, Kecamatan Syiah Kuala, Kota Banda Aceh: profil, pemerintahan, statistik penduduk, Masjid Besar Syuhada, wilayah, layanan, fasilitas publik, transparansi, berita, dan sumber data.') ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value);
