INSERT INTO `government_officials` (`name`,`position`,`description`,`sort_order`,`is_published`) SELECT 'Amanullah, S.Ag.','Keuchik Gampong Lamgugob','Terpilih pada Pilchiksung 22 September 2019 dan dilantik 19 November 2019. Jabatan masih terverifikasi dalam sumber publik pada 18 Agustus 2026.',1,1 WHERE NOT EXISTS (SELECT 1 FROM `government_officials` WHERE name='Amanullah, S.Ag.' AND position='Keuchik Gampong Lamgugob');
INSERT INTO `institutions` (`name`,`short_name`,`description`,`icon`,`sort_order`,`is_published`) SELECT 'Masjid Besar Syuhada Lamgugob','Masjid Syuhada','Masjid utama Gampong Lamgugob. Data sejarah, pengurus, program, dan fasilitas dikelola pada modul Masjid Syuhada.','landmark',1,1 WHERE NOT EXISTS (SELECT 1 FROM `institutions` WHERE name='Masjid Besar Syuhada Lamgugob');
INSERT INTO `institutions` (`name`,`short_name`,`description`,`icon`,`sort_order`,`is_published`) SELECT 'Koperasi Desa Merah Putih Syariah Gampong Lamgugob','Koperasi Merah Putih','Pembentukan melalui Musyawarah Desa Khusus tercatat pada 28 Mei 2025. Data registrasi publik mencantumkan SK AHU-0056306.AH.01.29.TAHUN 2025 dan NIK koperasi 1171040070015.','landmark',2,1 WHERE NOT EXISTS (SELECT 1 FROM `institutions` WHERE name='Koperasi Desa Merah Putih Syariah Gampong Lamgugob');
INSERT INTO `services` (`name`,`category`,`description`,`icon`,`estimated_time`,`flow_text`,`sort_order`,`is_online`,`is_published`) SELECT 'Pelaporan Penduduk Pendatang','Administrasi Kependudukan','Keuchik Lamgugob pada Agustus 2026 menyampaikan pentingnya pendataan warga pendatang, khususnya mahasiswa dan penghuni kos. Pendatang diminta melapor melalui kantor gampong, kepala dusun, atau kepala lorong. Persyaratan dokumen dan SOP belum dipublikasikan dalam sumber yang tersedia.','user-round-check',NULL,'Hubungi atau datang ke kantor gampong, kepala dusun, atau kepala lorong untuk mekanisme yang berlaku. Portal tidak menetapkan persyaratan sendiri sebelum SOP resmi tersedia.',1,0,1 WHERE NOT EXISTS (SELECT 1 FROM `services` WHERE name='Pelaporan Penduduk Pendatang');
