INSERT INTO village_milestones (slug,event_year,event_date,title,description,verification_status,source_url,sort_order,is_published) VALUES ('masjid-syuhada-akhir-1980an',1988,NULL,'Masjid Syuhada berkembang di lokasi sekarang','Sumber akademik menyebut pembangunan di lokasi Lamgugob sejak 1988, sementara dokumentasi lain mengaitkan pemindahan masjid lama dari Lamnyong dengan proyek penataan Krueng Aceh sekitar 1989.','historical','https://repository.ar-raniry.ac.id/952/1/skripsiTuti.pdf',1,1) ON DUPLICATE KEY UPDATE event_year=VALUES(event_year),event_date=VALUES(event_date),title=VALUES(title),description=VALUES(description),verification_status=VALUES(verification_status),source_url=VALUES(source_url),sort_order=VALUES(sort_order),is_published=VALUES(is_published);
INSERT INTO village_milestones (slug,event_year,event_date,title,description,verification_status,source_url,sort_order,is_published) VALUES ('dana-desa-2015',2015,NULL,'Dana Desa mulai diterima','Sumber lokal menyebut Dana Desa mulai diterima Lamgugob sejak 2015. Data ini bersifat historis dan perlu dibaca sesuai dokumen periode tersebut.','historical','https://repository.ar-raniry.ac.id/38688/1/Muhammad%2520Nabil%252C%2520170602138%252C%2520FEBI%252C%2520ES.pdf',2,1) ON DUPLICATE KEY UPDATE event_year=VALUES(event_year),event_date=VALUES(event_date),title=VALUES(title),description=VALUES(description),verification_status=VALUES(verification_status),source_url=VALUES(source_url),sort_order=VALUES(sort_order),is_published=VALUES(is_published);
INSERT INTO village_milestones (slug,event_year,event_date,title,description,verification_status,source_url,sort_order,is_published) VALUES ('masjid-bersih-2016',2016,NULL,'Masjid Syuhada memperoleh penghargaan kebersihan dan ketertiban','Masjid Syuhada pernah memperoleh penghargaan sebagai masjid paling bersih dan tertib di Banda Aceh pada 2016 dengan nilai penilaian 937 poin.','verified','https://prokopim.bandaacehkota.go.id/berita/5715/masjid-syuhada-lamgugob-masjid-paling-bersih-dan-tertib-di-banda-aceh.html',3,1) ON DUPLICATE KEY UPDATE event_year=VALUES(event_year),event_date=VALUES(event_date),title=VALUES(title),description=VALUES(description),verification_status=VALUES(verification_status),source_url=VALUES(source_url),sort_order=VALUES(sort_order),is_published=VALUES(is_published);
INSERT INTO village_milestones (slug,event_year,event_date,title,description,verification_status,source_url,sort_order,is_published) VALUES ('layak-anak-2019',2019,NULL,'Pencanangan menuju Gampong Layak Anak','Lamgugob bersama Kecamatan Syiah Kuala dicanangkan menuju Gampong dan Kecamatan Layak Anak pada Desember 2019. Ini merupakan peristiwa historis dan bukan klaim status aktif 2026.','verified','https://prokopim.bandaacehkota.go.id/berita/19589/wali-kota-canangkan-lamgugob-dan-syiah-kuala-menuju-gampong-dan-kecamatan-layak-anak.html',4,1) ON DUPLICATE KEY UPDATE event_year=VALUES(event_year),event_date=VALUES(event_date),title=VALUES(title),description=VALUES(description),verification_status=VALUES(verification_status),source_url=VALUES(source_url),sort_order=VALUES(sort_order),is_published=VALUES(is_published);
INSERT INTO village_milestones (slug,event_year,event_date,title,description,verification_status,source_url,sort_order,is_published) VALUES ('koperasi-merah-putih-2025',2025,'2025-05-28','Pembentukan Koperasi Desa Merah Putih Syariah','DPMG Kota Banda Aceh mencatat Musyawarah Desa Khusus pembentukan Koperasi Desa Merah Putih Syariah Gampong Lamgugob pada 28 Mei 2025.','verified','https://dpmg.bandaacehkota.go.id/category/berita/page/35/',5,1) ON DUPLICATE KEY UPDATE event_year=VALUES(event_year),event_date=VALUES(event_date),title=VALUES(title),description=VALUES(description),verification_status=VALUES(verification_status),source_url=VALUES(source_url),sort_order=VALUES(sort_order),is_published=VALUES(is_published);
INSERT INTO village_milestones (slug,event_year,event_date,title,description,verification_status,source_url,sort_order,is_published) VALUES ('renovasi-masjid-2025',2025,NULL,'Arsip kebutuhan renovasi Masjid Syuhada','Laporan Februari 2025 menyebut kebutuhan renovasi sekitar Rp1,2 miliar. Angka ini disimpan sebagai arsip 2025 dan bukan kebutuhan dana aktif saat ini.','historical','https://bidikindonesia.com/masjid-syuhada-lamgugob-butuh-12-milyar-untuk-renovasi/',6,1) ON DUPLICATE KEY UPDATE event_year=VALUES(event_year),event_date=VALUES(event_date),title=VALUES(title),description=VALUES(description),verification_status=VALUES(verification_status),source_url=VALUES(source_url),sort_order=VALUES(sort_order),is_published=VALUES(is_published);
INSERT INTO village_milestones (slug,event_year,event_date,title,description,verification_status,source_url,sort_order,is_published) VALUES ('pendataan-pendatang-2026',2026,'2026-08-18','Penguatan pendataan warga pendatang','Keuchik Lamgugob menekankan pentingnya pendataan warga pendatang, khususnya mahasiswa dan penghuni kos, untuk mendukung pelayanan dan ketertiban.','verified','https://kilatnews.co/keuchik-lamgugob-pendataan-penting-untuk-pelayanan-dan-ketertiban-warga-pendatang/',7,1) ON DUPLICATE KEY UPDATE event_year=VALUES(event_year),event_date=VALUES(event_date),title=VALUES(title),description=VALUES(description),verification_status=VALUES(verification_status),source_url=VALUES(source_url),sort_order=VALUES(sort_order),is_published=VALUES(is_published);
