INSERT INTO `faqs` (`question`,`answer`,`sort_order`,`is_published`) SELECT 'Berapa jumlah penduduk Gampong Lamgugob?','Berdasarkan Dukcapil Kota Banda Aceh melalui publikasi BPS untuk kondisi 2024, Lamgugob memiliki 4.448 jiwa: 2.180 laki-laki dan 2.268 perempuan. Tahun data adalah 2024 walaupun publikasinya terbit pada 2025.',1,1 WHERE NOT EXISTS (SELECT 1 FROM `faqs` WHERE question='Berapa jumlah penduduk Gampong Lamgugob?');
INSERT INTO `faqs` (`question`,`answer`,`sort_order`,`is_published`) SELECT 'Apa saja dusun di Gampong Lamgugob?','Gampong Lamgugob berada dalam Mukim Kayee Adang dan terdiri dari tiga dusun: Dusun Kayee Adang, Dusun Lamnyong, dan Dusun Tunggai.',2,1 WHERE NOT EXISTS (SELECT 1 FROM `faqs` WHERE question='Apa saja dusun di Gampong Lamgugob?');
INSERT INTO `faqs` (`question`,`answer`,`sort_order`,`is_published`) SELECT 'Di mana alamat Kantor Keuchik Lamgugob?','Alamat yang terdokumentasi adalah Jl. T. Lamgugob, Komplek Masjid Syuhada, Gampong Lamgugob, Kecamatan Syiah Kuala, Kota Banda Aceh 23115.',3,1 WHERE NOT EXISTS (SELECT 1 FROM `faqs` WHERE question='Di mana alamat Kantor Keuchik Lamgugob?');
INSERT INTO `faqs` (`question`,`answer`,`sort_order`,`is_published`) SELECT 'Bagaimana pelaporan penduduk pendatang?','Pada Agustus 2026 Keuchik Lamgugob menyampaikan bahwa pendatang, khususnya mahasiswa dan penghuni kos, diminta melapor melalui kantor gampong, kepala dusun, atau kepala lorong. Persyaratan dokumen dan SOP terbaru harus dikonfirmasi kepada Pemerintah Gampong.',4,1 WHERE NOT EXISTS (SELECT 1 FROM `faqs` WHERE question='Bagaimana pelaporan penduduk pendatang?');
INSERT INTO `faqs` (`question`,`answer`,`sort_order`,`is_published`) SELECT 'Apakah data BKM Masjid Syuhada sudah merupakan susunan terbaru?','Belum tentu. Susunan yang terdokumentasi memiliki masa khidmat 2021–2026. Ketua BKM masih terverifikasi melalui dokumen Mei 2026, tetapi susunan setelah periode tersebut perlu dikonfirmasi kembali.',5,1 WHERE NOT EXISTS (SELECT 1 FROM `faqs` WHERE question='Apakah data BKM Masjid Syuhada sudah merupakan susunan terbaru?');
INSERT INTO posts (type,title,slug,excerpt,content,category,image_url,source_url,published_at,is_published) VALUES ('news','Pendataan Warga Pendatang Penting untuk Pelayanan dan Ketertiban','pendataan-warga-pendatang-lamgugob-2026','Keuchik Lamgugob menekankan pentingnya pendataan warga pendatang, terutama mahasiswa dan penghuni kos.','Pada 18 Agustus 2026, Keuchik Lamgugob menyampaikan pentingnya pendataan penduduk pendatang untuk mendukung pelayanan dan ketertiban. Pendatang diminta melapor melalui kantor gampong, kepala dusun, atau kepala lorong.','Pemerintahan',NULL,'https://kilatnews.co/keuchik-lamgugob-pendataan-penting-untuk-pelayanan-dan-ketertiban-warga-pendatang/','2026-08-18 00:00:00',1) ON DUPLICATE KEY UPDATE title=VALUES(title),excerpt=VALUES(excerpt),content=VALUES(content),category=VALUES(category),source_url=VALUES(source_url),published_at=VALUES(published_at),is_published=VALUES(is_published);
INSERT INTO posts (type,title,slug,excerpt,content,category,image_url,source_url,published_at,is_published) VALUES ('news','Musyawarah Pembentukan Koperasi Desa Merah Putih Syariah','pembentukan-koperasi-merah-putih-lamgugob-2025','DPMG Kota Banda Aceh mencatat Musyawarah Desa Khusus pembentukan koperasi pada 28 Mei 2025.','Pada 28 Mei 2025 dilaksanakan Musyawarah Desa Khusus pembentukan Koperasi Desa Merah Putih Syariah Gampong Lamgugob. Data pengurus, produk, layanan, jam operasional, dan laporan kegiatan tetap perlu diperbarui dari koperasi.','Ekonomi',NULL,'https://dpmg.bandaacehkota.go.id/category/berita/page/35/','2025-05-28 00:00:00',1) ON DUPLICATE KEY UPDATE title=VALUES(title),excerpt=VALUES(excerpt),content=VALUES(content),category=VALUES(category),source_url=VALUES(source_url),published_at=VALUES(published_at),is_published=VALUES(is_published);
